    primes = []
    for num in numbers:
        if num > 1:
            is_prime = True
            for i in range(2, int(num**0.5) + 1):
                if (num % i) == 0:
                    is_prime = False
                    break
            if is_prime:
                primes.append(num)

    if len(primes) > 1:
        return max(primes) - min(primes)
    else:
        return None

prime_difference = find_prime_difference(sorted_list)

