class Trip:
    def __init__(self, distance, time):
        if distance < 0:
            raise ValueError("Distance must be non-negative.")
        if time <= 0:
            raise ValueError("Time must be positive.")
        self.__distance = distance
        self.__time = time

    def set_distance(self, distance):
        if distance >= 0:
            self.__distance = distance

    def set_time(self, time):
        if time > 0:
            self.__time = time

    def get_distance(self):
        return self.__distance

    def get_time(self):
        return self.__time

    def average_speed(self):
        return self.__distance / self.__time

    def __str__(self):
        return f"Distance = {self.__distance} km, Time = {self.__time} h"


if __name__ == "__main__":
    # Test case
    try:
        trip = Trip(350, 4)
        print(f"{trip.average_speed()} km/h")
        print(trip)

        # Attempt to set invalid distance and time
        trip.set_distance(-100)
        trip.set_time(0)
        print(trip)  # Should print the original valid state

    except ValueError as e:
        print(e)
```

This code snippet defines the `Trip` class according to the specifications and includes a test case that creates an instance of `Trip`, prints the average speed, and the string representation. It also attempts to set invalid values for distance and time, which should not affect the state of the instance.

